svg.script:
const links = document.querySelectorAll('.link');
const nodeShapes = document.querySelectorAll('.node-shape');
const nodeNames = document.querySelectorAll('.node-name');
const adjacency = {};
nodeShapes.forEach(n => {
  adjacency[n.id.replace('node:', '')] = { links: new Set(), nodes: new Set() };
});
links.forEach(l => {
  const parts = l.id.replace('link:', '').split('--to--');
  if (parts.length === 2) {
    const [src, tgt] = parts;
    if (adjacency[src]) { adjacency[src].links.add(l); adjacency[src].nodes.add(tgt); }
    if (adjacency[tgt]) { adjacency[tgt].links.add(l); adjacency[tgt].nodes.add(src); }
  }
});
function highlight(id) {
  const adj = adjacency[id];
  if (!adj) return;
  const n = document.getElementById('node:' + id);
  const t = document.getElementById('text:' + id);
  if (n) n.classList.add('highlight');
  if (t) t.classList.add('highlight');
  adj.links.forEach(l => l.classList.add('highlight'));
  adj.nodes.forEach(nid => {
    const nn = document.getElementById('node:' + nid);
    const nt = document.getElementById('text:' + nid);
    if (nn) nn.classList.add('highlight');
    if (nt) nt.classList.add('highlight');
  });
}
function unhighlight() {
  document.querySelectorAll('.highlight').forEach(el => el.classList.remove('highlight'));
}
[...nodeShapes, ...nodeNames].forEach(el => {
  const id = el.id.replace(/^(node|text):/, '');
  el.addEventListener('mouseenter', () => highlight(id));
  el.addEventListener('mouseleave', unhighlight);
});
